 "content": "def transform(grid):
    n = len(grid)
    m = len(grid[0])
    assert n == m
    def rot90(a):
        return [list(row) for row in zip(*a[::-1])]
    def rot180(a):
        return [row[::-1] for row in a[::-1]]
    def rot270(a):
        return [list(row) for row in zip(*a)][::-1]
    a = [row[:] for row in grid]
    blocks = [a, rot90(a), rot270(a), rot180(a)]
    out = [[0] * (2*m) for _ in range(2*n)]
    for bi, block in enumerate(blocks):
        ro = 0 if bi < 2 else n
        co = 0 if bi % 2 == 0 else m
        for r in range(n):
            out[ro+r][co:co+m] = block[r]
    return out
